# Writes leaves.txt: falling leaves that never leave the clearing.
#
# Every leaf falls inside a 3.9 m circle (the clearing is a 12-gon of radius 5, its rim 4.83 m from
# the centre; the +-0.4 m sway and a leaf's own half-size, <= 0.127 m, keep it inside the rim), out of
# the cabin's footprint (cabin at hedra (0.3, 1.0), 3.7 x 2.7 m with its roof and chimney), and its
# fall ends just under the ground: below z 0 it is inside the clearing's 0.5 m slab, hidden, and it
# never falls into the void under the island.
#
# How (the winter snowfall's banded column): a column of leaves from B (-0.365) to B + D (8.64) is
# cut into K thin bands, one object (one bone) each. Every band falls at the same speed, swaying
# +-0.4 m in X with a 10 s period (the wind, the same for all); when a band is entirely under the
# ground (between B and B + H, inside the slab) it jumps back to the top of the column, which is above
# the frame (the default 8.5 m ortho view shows at most ~8.3 m up, at the clearing's front edge). The
# bands sit one band apart, so the union is a uniform column at every frame, and the loop (L s, every
# band falls the whole column once) has no seam. Jumps land on the bake's 10 fps samples (every
# 0.5 s, a whole number of hedra frames too), so no sample catches a band in mid jump.
# Run: python3 make_leaves.py
import math
import random

import numpy as np

rnd = random.Random(17)
R = 3.9              # leaves inside this circle (m)
B = -0.365           # column bottom: under the ground, inside the slab (bottom -0.5, a leaf reaches 0.127)
K = 40               # bands (bones)
L = 20.0             # loop (s): one fall of the whole column
D = 9.0              # column height (m): 0.45 m/s
H = D / K            # band height 0.225: B + H + 0.127 < 0, so a band jumps only when all of it is hidden
N = 62               # leaves (the old field's density, ~7 a metre)
SWAY, PERIOD = 0.4, 10.0
FPS = 24
F = round(L * FPS)   # 480
step = F // K        # 12 frames (0.5 s, a 10 fps sample) between the bands' jumps
assert F % K == 0 and step % 12 == 0 and B + H + 0.127 < 0 and B - 0.127 > -0.5


def euler(rx, ry, rz):
    """Blender XYZ euler (degrees) as a matrix."""
    a, b, c = (math.radians(x) for x in (rx, ry, rz))
    X = np.array([[1, 0, 0], [0, math.cos(a), -math.sin(a)], [0, math.sin(a), math.cos(a)]])
    Y = np.array([[math.cos(b), 0, math.sin(b)], [0, 1, 0], [-math.sin(b), 0, math.cos(b)]])
    Z = np.array([[math.cos(c), -math.sin(c), 0], [math.sin(c), math.cos(c), 0], [0, 0, 1]])
    return Z @ Y @ X


HALF = np.array([0.1, 0.075, 0.02])
leaves = [[] for _ in range(K)]
n = 0
while n < N:
    x, y = rnd.uniform(-R, R), rnd.uniform(-R, R)
    if x * x + y * y > R * R:
        continue
    if -1.7 < x < 2.4 and -0.5 < y < 2.5:
        continue
    rx, ry, rz = rnd.uniform(-60, 60), rnd.uniform(-60, 60), rnd.uniform(0, 180)
    assert np.abs(euler(rx, ry, rz)[2]) @ HALF <= 0.127
    k = n % K        # stratified: every band gets its share
    leaves[k].append((x, y, B + (k + rnd.random()) * H, rx, ry, rz, "A" if n % 2 == 0 else "B"))
    n += 1

v = D / L


def sway(t):
    """The wind: a triangle wave, 0 at t 0, +SWAY at a quarter period."""
    u = (t / PERIOD) % 1.0
    return SWAY * (4 * u if u < 0.25 else 2 - 4 * u if u < 0.75 else 4 * u - 4)


lines = ["# Falling leaves: generated by make_leaves.py (see there). Up Z.", "new", f"fps {FPS}",
         f"frame range 0 {F}"]
groups, names_a, names_b = [], [], []
for k in range(K):
    names = []
    for i, (x, y, z, rx, ry, rz, m) in enumerate(leaves[k]):
        nm = f"F{k}_{i}"
        lines.append(f"add mesh cube --name {nm} --size 1 --location {x:.3f} {y:.3f} {z:.3f}")
        lines.append("scale 0.2 0.15 0.04")
        lines.append("apply --scale")
        lines.append(f"set rotation {rx:.0f} {ry:.0f} {rz:.0f}")
        lines.append("apply --rotation")
        names.append(nm)
        (names_a if m == "A" else names_b).append(nm)
    groups.append(names)

lines.append("material new LeafA --base-color 0.949 0.827 0.671 --no-slot")
lines.append("material new LeafB --base-color 0.776 0.624 0.647 --no-slot")
lines.append("select " + " ".join(names_a))
lines.append("material assign LeafA")
lines.append("select " + " ".join(names_b))
lines.append("material assign LeafB")

bands = []
for k, names in enumerate(groups):
    g = f"Leaves{k:02d}"
    lines.append("select " + " ".join(names))
    lines.append(f"active {names[0]}")
    if len(names) > 1:
        lines.append("join")
    lines.append(f"rename {names[0]} {g}")
    lines.append("cursor set 0 0 0")
    lines.append("origin set --to cursor")
    bands.append(g)

# keys: band k starts at B + k H (offset 0), falls to B at frame k * step, jumps to the column top
# one frame later, and falls back to its start at frame F (band 0 starts at the top, offset +D);
# the sway is keyed at its quarter periods, so every segment between keys is a straight line.
q = round(PERIOD / 4 * FPS)
for k, g in enumerate(bands):
    fj = k * step
    frames = sorted(set(range(0, F + 1, q)) | ({fj, fj + 1} if k else set()))

    def dz(f):
        t = f / FPS
        if k == 0:
            return D - v * t
        return -v * t if f <= fj else D - v * t
    lines.append(f"select {g}")
    lines.append(f"active {g}")
    for f in frames:
        lines.append(f"set location {sway(f / FPS):.5f} 0 {dz(f):.5f}")
        lines.append(f"keyframe insert --channels loc --frame {f}")
lines.append("select " + " ".join(bands))
lines.append("keyframe interpolation linear --all")
lines.append("frame set 0")
lines.append("shade flat")
lines.append("export leaves.glb --bake-animations")
open("leaves.txt", "w").write("\n".join(lines) + "\n")
print(f"{N} leaves in {K} bands of {H:.3f} m, column {B} .. {B + D:.2f} m, {L} s loop; per band:",
      [len(g) for g in groups])
